package com.acme.core.infrastructure.security;

import com.acme.core.common.core.CurrentClock;
import com.acme.core.application.auth.AuthService;
import com.acme.core.application.rbac.UserQueryService;
import com.acme.core.common.security.TokenService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Authentication bean wiring (generated by engineering-platform 0.1.0).
 */
@Configuration
public class AuthBeansConfig {

    @Value("#{environment['auth.token.expiration-seconds'] ?: 3600}")
    private long expirationSeconds;

    @Bean
    public CurrentClock currentClock() {
        return CurrentClock.system();
    }

    @Bean
    public AuthService authService(UserQueryService userQueryService, TokenService tokenService,
                                   CurrentClock currentClock) {
        return new AuthService(userQueryService, tokenService, currentClock, expirationSeconds);
    }
}
